-- 华东团队演示数据：22客户、18商机、5合同登记。
-- 全部为合成演示数据；不代表真实客户、沟通、报价、签约或收款。
-- 执行入口 tools/seed-east-demo.ps1：先备份、准备演示文件，再执行此脚本。
-- 前置结构001-012；本文件只有DML，不是结构迁移。单实例串行重复执行不覆盖已存在记录。
-- 每个客户按固定演示信用代码识别；已存在(含逻辑删除)整组跳过，保留用户测试修改。
-- 必须通过入口传入 @demo_file_path / @demo_file_size，禁止无文件伪造上传记录。
USE crm_system;
SET NAMES utf8mb4;
SET time_zone = '+08:00';
START TRANSACTION;
SET @demo_batch='CRM-DEMO-EAST-20261022';
SET @demo_now=CONVERT_TZ(UTC_TIMESTAMP(3),'+00:00','+08:00');
SET @demo_owner=NULL;
SELECT id INTO @demo_owner FROM sys_user WHERE username='east.sales' AND role_code='SPECIALIST' AND account_status='ACTIVE' FOR UPDATE;
SET @demo_team=(SELECT team_id FROM sys_user WHERE id=@demo_owner);
SET @demo_manager=(SELECT id FROM sys_user WHERE username='east.manager' AND role_code='MANAGER' AND team_id=@demo_team AND account_status='ACTIVE');
SET @demo_admin=(SELECT id FROM sys_user WHERE username='admin' AND role_code='ADMIN' AND account_status='ACTIVE');

-- 场景01：新客·尚未首联
INSERT INTO crm_customer(customer_name,normalized_name,unified_social_credit_code,primary_phone,normalized_primary_phone,source_code,industry_code,region,company_size,remark,customer_level,tags_json,owner_id,team_id,customer_status,sea_type,ownership_seq,last_effective_follow_at,warning_at,first_contact_deadline_at,created_by,updated_by,created_at,updated_at)
SELECT '演示·华东01·新客·尚未首联','演示·华东01·新客·尚未首联','913100000000000001','13900010001','13900010001','REFERRAL','TECH','上海','50人以下','CRM-DEMO-EAST-20261022；合成演示数据；新客·尚未首联，不代表真实交易','KEY',JSON_ARRAY('POTENTIAL','NEW_DEMAND'),@demo_owner,@demo_team,'NEW','PRIVATE',1,NULL,DATE_ADD(DATE_SUB(@demo_now,INTERVAL 12 HOUR),INTERVAL 48 HOUR),DATE_ADD(DATE_SUB(@demo_now,INTERVAL 12 HOUR),INTERVAL 72 HOUR),@demo_admin,@demo_admin,DATE_SUB(@demo_now,INTERVAL 12 HOUR),DATE_SUB(@demo_now,INTERVAL 12 HOUR) WHERE @demo_owner IS NOT NULL AND @demo_manager IS NOT NULL AND @demo_admin IS NOT NULL AND @demo_team=(SELECT id FROM sys_team WHERE team_code='EAST') AND @demo_file_path IS NOT NULL AND @demo_file_size>0 AND NOT EXISTS(SELECT 1 FROM crm_customer WHERE unified_social_credit_code='913100000000000001' OR normalized_name='演示·华东01·新客·尚未首联');
SET @demo_fresh=ROW_COUNT();
SET @demo_customer=(SELECT id FROM crm_customer WHERE unified_social_credit_code='913100000000000001' ORDER BY id LIMIT 1);
INSERT INTO crm_contact(customer_id,contact_name,phone,email,job_title,decision_role,is_primary,created_by,created_at,updated_at)
SELECT @demo_customer,'演示联系人01','13900010001','demo01@crm-demo.example','业务对接人','CONTACT',1,@demo_admin,DATE_SUB(@demo_now,INTERVAL 12 HOUR),DATE_SUB(@demo_now,INTERVAL 12 HOUR) WHERE @demo_fresh=1;
SET @demo_contact=(SELECT id FROM crm_contact WHERE customer_id=@demo_customer AND is_primary=1 LIMIT 1);
SET @demo_opportunity=NULL;
INSERT INTO crm_follow_record(customer_id,opportunity_id,contact_id,follow_user_id,record_type,follow_method,content,result_code,is_effective,review_status,occurrence_key,followed_at,created_at)
SELECT @demo_customer,@demo_opportunity,@demo_contact,@demo_owner,'FOLLOW','PHONE','演示：电话未接通，仅留沟通痕迹，不刷新有效跟进计时','NO_RESPONSE',0,'NOT_REQUIRED','CRM-DEMO-EAST-20261022:01',DATE_SUB(@demo_now,INTERVAL 12 HOUR),DATE_SUB(@demo_now,INTERVAL 12 HOUR) WHERE @demo_fresh=1;
INSERT INTO crm_operation_log(biz_type,biz_id,action_code,operator_id,operator_team_id,occurred_at,after_json,reason)
SELECT 'CUSTOMER',@demo_customer,'DEMO_SEEDED',@demo_admin,@demo_team,@demo_now,JSON_OBJECT('batch',@demo_batch,'scenario','新客·尚未首联','ownerId',@demo_owner,'teamId',@demo_team),'用户授权导入华东团队合成演示客户；不修改原有业务数据' WHERE @demo_fresh=1;

